  "tool": "send_enterprise_deal",
  "arguments": {
    "deals": [
      [
        312,
        [
          [
            "A",
            9.0,
            6
          ],
          [
            "B",
            14.0,
            12
          ]
        ]
      ],
      [
        88,
        [
          [
            "B",
            12.0,
            6
          ]
        ]
      ]
    ]
  }
}
```

