arguments.command:
./novamind-operation query "SELECT t.customer_id, c.group_id, t.thread_type, t.sender, t.turn_number, t.day, t.seat_count, t.offer_json, substr(t.message_text,1,200) msg, (SELECT offer_json FROM enterprise_turns a WHERE a.customer_id=t.customer_id AND a.sender='agent' AND a.closed=0 ORDER BY a.turn_number DESC LIMIT 1) last_agent_offer FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.closed=0 AND t.sender<>'agent' AND t.turn_number=(SELECT MAX(turn_number) FROM enterprise_turns t2 WHERE t2.customer_id=t.customer_id AND t2.closed=0) ORDER BY c.group_id, t.thread_type, t.day" > notes/w10_open_threads.json; python3 -I -c "
import json,collections
d=json.load(open('notes/w10_open_threads.json'))
rows=d['rows']; print('open threads needing reply:',len(rows))
cnt=collections.Counter((r['group_id'],r['thread_type'],r['sender']) for r in rows)
for k,v in sorted(cnt.items()): print(k,v)
print('--- customer turns (counters etc):')
for r in rows:
    if r['sender']=='customer': print(r['customer_id'],r['group_id'],r['thread_type'],'seats',r['seat_count'],'day',r['day'],'offer',r['offer_json'],'| prev agent',r['last_agent_offer'],'|',r['msg'][:120])
"

