RETAIN = {"E1": [["B", 16.0], ["A", 12.0]], "E2": [["B", 59.0], ["A", 39.0]], "E3": [["B", 59.0], ["A", 45.0]],
          "D_E09": [["B", 39.0], ["A", 29.0]], "D_E02": [["B", 39.0], ["A", 29.0]], "D_E08": [["B", 79.0], ["A", 59.0]]}

rows = nm.query("""SELECT t.customer_id, c.group_id, t.thread_type, t.sender, t.offer_json
  FROM enterprise_turns t JOIN customers c USING(customer_id)
  WHERE t.closed=0 AND t.sender<>'agent'
    AND t.turn_number=(SELECT MAX(turn_number) FROM enterprise_turns t2 WHERE t2.customer_id=t.customer_id AND t2.closed=0)""")["rows"]
deals, skipped = [], []
for r in rows:
    g, tt, cid = r["group_id"], r["thread_type"], r["customer_id"]
    if tt == "churn_prevention":
        off = RETAIN.get(g)
    elif r["sender"] == "customer":
        if g == "E2":
            try: p = float(json.loads(r["offer_json"] or "{}").get("price", 0))
            except Exception: p = 0
            off = [["B", max(p + 8.0, 50.0)], ["A", 42.0]] if p >= 40 else [["A", 42.0], ["B", 62.0]]
        else:
