print("deals to send:", len(deals), "skipped:", skipped)
ok = fail = 0
for i in range(0, len(deals), 40):
    res = nm.enterprise.send_enterprise_deal(deals[i:i+40])
    for x in res.get("results", []):
        if x.get("success"): ok += 1
        else: fail += 1; print("FAIL", x)
print(f"enterprise deals sent ok={ok} fail={fail}")

show("spend", nm.marketing.set_daily_spend(operations=30000, development=12000))
show("targeted ops", nm.analytics.set_targeted_ops_spend(by_group={"E1": 3000, "E2": 4000, "E3": 3000, "D_E09": 1500, "D_E02": 1000, "D_E08": 1000}))
show("prices", nm.pricing.set_prices(A=64.0, B=159.0, C=199.0))
show("promo", nm.pricing.set_promotion(global_promotion=0.0, by_group_plan={"S1": {"A": 49.0}, "S2": {"B": 30.0}, "D_S07": {"A": 25.0}}))
show("dev", nm.analytics.set_targeted_dev_spend({"S2": 5000, "S3": 5000, "S1": 4000, "E3": 12000, "E2": 12000, "E1": 4000, "D_E09": 8000, "D_E02": 5000, "D_S07": 12000, "D_S10": 8000, "D_E08": 6000}))
