import json,collections,re
d=json.load(open('notes/w11_open_threads.json'))
rows=d['rows']; print('open threads needing reply:',len(rows))
cnt=collections.Counter((r['group_id'],r['thread_type'],r['sender']) for r in rows)
for k,v in sorted(cnt.items()): print(k,v)
print('--- counter distributions (customer turns, new_lead): group plan -> prices')
dist=collections.defaultdict(list)
for r in rows:
    if r['sender']=='customer' and r['thread_type']=='new_lead':
        try: o=json.loads(r['offer_json'] or '{}')
        except: o={}
        m=re.search(r'Plan (\w)',r['msg'] or '')
        plan=m.group(1) if m else '?'
        dist[(r['group_id'],plan)].append((o.get('price'),r['seat_count'],r['turn_number']))
for k,v in sorted(dist.items()):
    prices=sorted(p for p,_,_ in v if p is not None)
    print(k,'n=',len(v),'prices=',prices[:60])
print('--- churn_prevention / other customer turns:')
for r in rows:
    if r['sender']=='customer' and r['thread_type']!='new_lead':
        print(r['customer_id'],r['group_id'],r['thread_type'],'seats',r['seat_count'],'turn',r['turn_number'],'|',(r['msg'] or '')[:100],'| prev',r['last_agent_offer'])
EOF

