import json,collections,re
d=json.load(open('notes/w12_open_threads.json'))
rows=d['rows']; print('open threads needing reply:',len(rows))
cnt=collections.Counter((r['group_id'],r['thread_type'],r['sender']) for r in rows)
for k,v in sorted(cnt.items()): print(k,v)
print('--- counter distributions (customer turns, new_lead): group plan -> n, median, prices')
dist=collections.defaultdict(list)
for r in rows:
    if r['sender']=='customer' and r['thread_type']=='new_lead':
        try: o=json.loads(r['offer_json'] or '{}')
        except: o={}
        m=re.search(r'Plan (\w)',r['msg'] or '')
        dist[(r['group_id'],m.group(1) if m else '?')].append(o.get('price'))
for k,v in sorted(dist.items()):
    prices=sorted(p for p in v if p is not None)
    med=prices[len(prices)//2] if prices else None
    print(k,'n=',len(v),'median=',med,'prices=',prices[:50])
print('--- non-new_lead customer turns:')
for r in rows:
    if r['sender']=='customer' and r['thread_type']!='new_lead':
        print(r['customer_id'],r['group_id'],r['thread_type'],'seats',r['seat_count'],'turn',r['turn_number'],'|',(r['msg'] or '')[:90],'| prev',(r['last_agent_offer'] or '')[:90])
EOF

