arguments.command:
cat > scripts/w13_setup.py <<'EOF'
import json
import novamind_api as nm
def show(label, r): print(f"--- {label}"); print(json.dumps(r, indent=1)[:1500])

NEW = {"E2": [["A", 45.0], ["B", 69.0]], "E3": [["B", 69.0], ["A", 49.0]], "E1": [["B", 17.0], ["A", 12.0]],
       "D_E09": [["B", 49.0], ["A", 39.0]], "D_E02": [["B", 49.0], ["A", 39.0]], "D_E08": [["B", 89.0], ["A", 69.0]],
       "D_E07": [["B", 119.0], ["A", 89.0]]}
RETAIN = {"E1": [["B", 16.0], ["A", 12.0]], "E2": [["B", 59.0], ["A", 39.0]], "E3": [["B", 59.0], ["A", 45.0]],
          "D_E09": [["B", 39.0], ["A", 29.0]], "D_E02": [["B", 39.0], ["A", 29.0]], "D_E08": [["B", 79.0], ["A", 59.0]],
          "D_E07": [["B", 99.0], ["A", 79.0]]}
def counter_offer(g, p):
    if g == "E2":  return [["B", min(p + 5.0, 69.0)], ["A", 42.0]] if p >= 45 else [["B", 62.0], ["A", 42.0]]
    if g == "E3":  return [["B", min(p + 5.0, 69.0)], ["A", 47.0]] if p >= 50 else [["B", 65.0], ["A", 47.0]]
    if g == "E1":  return [["B", 16.0], ["A", 12.0]]
    if g in ("D_E09", "D_E02"): return [["B", min(p + 4.0, 49.0)], ["A", 35.0]] if p >= 35 else [["B", 45.0], ["A", 35.0]]
    if g == "D_E08": return [["B", 85.0], ["A", 65.0]]
    if g == "D_E07": return [["B", 109.0], ["A", 85.0]]
    return None

rows = nm.query("""SELECT t.customer_id, c.group_id, t.thread_type, t.sender, t.offer_json
  FROM enterprise_turns t JOIN customers c USING(customer_id) JOIN subscriptions s ON s.customer_id=t.customer_id
  WHERE t.turn_number=(SELECT MAX(turn_number) FROM enterprise_turns t2 WHERE t2.customer_id=t.customer_id)
    AND t.closed=0 AND t.sender<>'agent' AND s.status IN ('lead','subscribed')""")["rows"]
deals, skipped = [], []
for r in rows:
    g, tt, cid = r["group_id"], r["thread_type"], r["customer_id"]
    if tt in ("churn_prevention", "renewal"):
        off = RETAIN.get(g)
    elif r["sender"] == "customer":
        try: p = float(json.loads(r["offer_json"] or "{}").get("price", 0) or 0)
        except Exception: p = 0.0
        off = counter_offer(g, p)
    else:
        off = NEW.get(g)
    if off: deals.append([cid, off])
    else: skipped.append(r)
print("deals to send:", len(deals), "skipped:", skipped)
ok = fail = 0
def send(batch):
    global ok, fail
    try:
        res = nm.enterprise.send_enterprise_deal(batch)
        for x in res.get("results", []):
            if x.get("success"): ok += 1
            else: fail += 1; print("FAIL", x)
    except nm.NovaMindAPIError as e:
        if len(batch) == 1: fail += 1; print("FAIL single", batch[0][0], str(e)[:160])
        else:
            for d in batch: send([d])
for i in range(0, len(deals), 40): send(deals[i:i+40])
print(f"enterprise deals sent ok={ok} fail={fail}")

# Renegotiation test: small established accounts with no open thread
reneg = nm.query("""SELECT s.customer_id, c.group_id, s.seat_count, s.effective_price FROM subscriptions s JOIN customers c USING(customer_id)
  WHERE c.customer_type='large' AND s.status='subscribed' AND s.start_day <= 70
    AND NOT EXISTS (SELECT 1 FROM enterprise_turns t WHERE t.customer_id=s.customer_id AND t.closed=0
                    AND t.turn_number=(SELECT MAX(turn_number) FROM enterprise_turns t2 WHERE t2.customer_id=s.customer_id))
  ORDER BY s.seat_count ASC""")["rows"]
tests = []
picked = {"E2": 0, "E1": 0, "E3": 0}
for r in reneg:
    g = r["group_id"]
    if g == "E2" and picked[g] < 6 and r["effective_price"] <= 69: tests.append([r["customer_id"], [["B", 79.0]]]); picked[g] += 1
    elif g == "E1" and picked[g] < 6 and r["effective_price"] <= 17: tests.append([r["customer_id"], [["B", 19.0]]]); picked[g] += 1
    elif g == "E3" and picked[g] < 2 and r["effective_price"] <= 69: tests.append([r["customer_id"], [["B", 79.0]]]); picked[g] += 1
print("renegotiation tests:", tests)
if tests:
    show("renegotiation", nm.enterprise.send_enterprise_deal(tests))
json.dump(tests, open("notes/reneg_test_day84.json", "w"))

show("capacity", nm.infrastructure.set_capacity_tier(7))
show("spend", nm.marketing.set_daily_spend(operations=50000, development=30000))
show("targeted ops", nm.analytics.set_targeted_ops_spend(by_group={"E1": 5000, "E2": 8000, "E3": 4000, "D_E09": 2000, "D_E02": 2000, "D_E08": 1000, "D_E07": 1000}))
