cat > scripts/enterprise_lib.py <<'EOF'
"""Shared enterprise negotiation helpers (open-thread detection by latest message_id)."""
import json
import novamind_api as nm

NEW = {"E2": [["A", 45.0], ["B", 69.0]], "E3": [["B", 69.0], ["A", 49.0]], "E1": [["B", 17.0], ["A", 12.0]],
       "D_E09": [["B", 49.0], ["A", 39.0]], "D_E02": [["B", 49.0], ["A", 39.0]], "D_E08": [["B", 89.0], ["A", 69.0]],
       "D_E07": [["B", 119.0], ["A", 89.0]]}

def counter_offer(g, p):
    if g == "E2":  return [["B", min(p + 5.0, 69.0)], ["A", 42.0]] if p >= 45 else [["B", 62.0], ["A", 42.0]]
    if g == "E3":  return [["B", min(p + 5.0, 69.0)], ["A", 47.0]] if p >= 50 else [["B", 65.0], ["A", 47.0]]
    if g == "E1":  return [["B", 16.0], ["A", 12.0]]
    if g in ("D_E09", "D_E02"): return [["B", min(p + 4.0, 49.0)], ["A", 35.0]] if p >= 35 else [["B", 45.0], ["A", 35.0]]
    if g == "D_E08": return [["B", 85.0], ["A", 65.0]]
    if g == "D_E07": return [["B", 109.0], ["A", 85.0]]
    return NEW.get(g)

def retain_offer(cur):
    b = round(max(cur * 0.8, cur - 3.0), 0) if cur >= 20 else round(cur - 3.0, 0)
    a = max(round(cur * 0.6, 0), 5.0)
    return [["B", float(b)], ["A", float(a)]]

def pending_threads():
    """Latest message per customer (by message_id); open and not ours."""
    return nm.query("""SELECT t.customer_id, c.group_id, t.thread_type, t.sender, t.offer_json, s.status, s.effective_price, s.seat_count
      FROM enterprise_turns t JOIN customers c USING(customer_id) JOIN subscriptions s ON s.customer_id=t.customer_id
      WHERE t.message_id=(SELECT MAX(message_id) FROM enterprise_turns t2 WHERE t2.customer_id=t.customer_id)
        AND t.closed=0 AND t.sender<>'agent' AND s.status IN ('lead','subscribed')""")["rows"]

def build_deals(rows, new=NEW, counter=counter_offer, retain=retain_offer):
    deals, skipped = [], []
    for r in rows:
        g, tt, cid = r["group_id"], r["thread_type"], r["customer_id"]
        try: p = float(json.loads(r["offer_json"] or "{}").get("price", 0) or 0)
        except Exception: p = 0.0
        cur = float(r["effective_price"] or 0)
        if tt == "renegotiation":
            off = [["B", p if p > cur else cur]]
        elif tt in ("churn_prevention", "renewal"):
            off = retain(cur)
        elif r["sender"] == "customer":
            off = counter(g, p)
        else:
            off = new.get(g)
        if off: deals.append([cid, off])
        else: skipped.append(r)
    return deals, skipped

def send_all(deals, batch=40):
    ok = fail = 0
    def send(b):
        nonlocal ok, fail
        try:
            res = nm.enterprise.send_enterprise_deal(b)
            for x in res.get("results", []):
                if x.get("success"): ok += 1
                else: fail += 1; print("FAIL", x)
        except nm.NovaMindAPIError as e:
            if len(b) == 1: fail += 1; print("FAIL single", b[0][0], str(e)[:160])
            else:
                for d in b: send([d])
    for i in range(0, len(deals), batch): send(deals[i:i+batch])
    return ok, fail

def open_customers():
    rows = nm.query("""SELECT t.customer_id FROM enterprise_turns t
      WHERE t.message_id=(SELECT MAX(message_id) FROM enterprise_turns t2 WHERE t2.customer_id=t.customer_id) AND t.closed=0""")["rows"]
    return {r["customer_id"] for r in rows}
EOF
