cat > scripts/summarize_threads2.py <<'EOF'
import json, collections, sys, statistics
sys.path.insert(0, "scripts")
import enterprise_lib as el
rows = el.pending_threads()
print("open threads needing reply:", len(rows))
cnt = collections.Counter((r["group_id"], r["thread_type"], r["sender"]) for r in rows)
for k, v in sorted(cnt.items()): print(k, v)
def price(r):
    try: return float(json.loads(r["offer_json"] or "{}").get("price", 0) or 0)
    except Exception: return 0.0
print("--- new_lead counters: group -> n, median")
d = collections.defaultdict(list)
for r in rows:
    if r["sender"] == "customer" and r["thread_type"] == "new_lead": d[r["group_id"]].append(price(r))
for k, v in sorted(d.items()):
    v = sorted(v); print(k, "n=", len(v), "median=", v[len(v)//2], "min", v[0], "max", v[-1])
print("--- renegotiation counters: group -> n, median counter, median current, ratio stats, seats")
d = collections.defaultdict(list)
for r in rows:
    if r["thread_type"] == "renegotiation": d[r["group_id"]].append((price(r), float(r["effective_price"] or 0), r["seat_count"]))
for k, v in sorted(d.items()):
    ps = sorted(p for p, _, _ in v); cs = [c for _, c, _ in v]; ratios = sorted(p / c for p, c, _ in v if c)
    below = sum(1 for p, c, _ in v if p < c)
    print(k, "n=", len(v), "median_counter=", ps[len(ps)//2], "median_cur=", statistics.median(cs), "median_ratio=", round(ratios[len(ratios)//2], 2), "below_current=", below, "seats=", sum(s for _, _, s in v))
EOF
